#requires -Version 5.1
<#
.SYNOPSIS
Provisions a local coding environment on Windows.
.DESCRIPTION
AuditOnly inspects hardware, CLI tools, local state and online metadata.
It installs nothing and loads no models. CLI tools may write their own caches/logs
or initialize a background service. Normal provisioning installs missing tools,
verifies local models and creates an isolated VS Code profile. Models are suggested
per role and downloaded after confirmation when needed. InstallRoot defaults to
this script directory. An existing installation in LOCALAPPDATA/ShadowLocalAI can
be reused or copied. Only typing y permits changes; AuditOnly does not prompt.
Base programs retain their standard paths, models their configured LM Studio path.
Global configuration and external models are preserved. The embedded ZIP contains
readable source files; SHA256 verifies integrity, not publisher authenticity.
#>
[CmdletBinding()]
param(
    [ValidateNotNullOrEmpty()][string]$InstallRoot,
    [switch]$AuditOnly,
    [ValidateSet('Keep','Configure')][string]$ModelAction,
    [ValidateSet('Single','Dual')][string]$ModelMode='Dual',
    [ValidateSet('frozen','latest','lts')][string]$UpdatePolicy,
    [ValidateSet('Off','OnDemand','Automatic')][string]$IndexingMode='Off',
    [switch]$IncludeFastModel,
    [switch]$AllowPartialGpuOffload,
    [switch]$AllowUnfitAttempt,
    [ValidateRange(1024,65535)][int]$RouterPort=1235,
    [ValidateSet('Auto','Qwen27B','GptOss20B')][string]$PreferredModel='Auto',
    [string]$ModelKey,
    [string]$ApiTokenEnvironmentVariable='LOKIENTE_LM_API_KEY',
    [ValidateRange(8192,65536)][int]$ContextLength=32768,
    [ValidateRange(1024,65535)][int]$Port=1234,
    [string[]]$ProjectPath=@(),
    [switch]$SkipModelDownload,
    [switch]$UpdateManaged,
    [switch]$NoShortcut
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$IndexingMode=switch($IndexingMode){'Off'{'Off'} 'OnDemand'{'OnDemand'} 'Automatic'{'Automatic'}}
if(-not $PSBoundParameters.ContainsKey('InstallRoot')){
    $InstallRoot=Split-Path -Parent $MyInvocation.MyCommand.Path
}
$bundleVersion='2026.11.23.7'
